import sys

MOD = 998244353

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    m = int(input_data[1])
    p = int(input_data[2])
    q = int(input_data[3])
    segment = q - p + 1
    if p % 2 == 0:
        segment = segment - segment // 2
    else:
        segment //= 2
    otherSegment = (q - p + 1) - segment
    cacheMap = [{}, {}]

    def computeRecursive(x, y, total, type, cacheMap):
        if total in cacheMap[type]:
            return cacheMap[type][total]
        if total == 1:
            return x if type == 0 else y
        if total % 2 == 1:
            res = (x * computeRecursive(x, y, total - 1, type, cacheMap) + y * computeRecursive(x, y, total - 1, (type + 1) % 2, cacheMap)) % MOD
            return res
        else:
            half = total // 2
            ch = computeRecursive(x, y, half, 0, cacheMap)
            nch = computeRecursive(x, y, half, 1, cacheMap)
            if type == 0:
                ans = (ch * ch + nch * nch) % MOD
            else:
                ans = (2 * ch * nch) % MOD
            cacheMap[type][total] = ans
            return ans

    def computeCombination(x, st):
        if st == 0:
            return 1
        if st == 1:
            return x
        half = st // 2
        res = computeCombination(x, half)
        if st % 2 == 0:
            return (res * res) % MOD
        else:
            return ((res * res) % MOD * x) % MOD

    if ((n & m) % 2) == 0:
        result = computeRecursive(segment, otherSegment, n * m, 0, cacheMap)
        print(result)
    else:
        result = computeCombination(segment + otherSegment, n * m)
        print(result)

if __name__ == "__main__":
    main()

